def count_nums(arr):
    def signed_digit_sum(n):
        if n >= 0:
            return sum(int(d) for d in str(n))
        digits = [int(d) for d in str(-n)]
        digits[0] *= -1
        return sum(digits)

    return sum(1 for x in arr if signed_digit_sum(x) > 0)
